  private_key = file(var.private_key_path)
}

resource "null_resource" "cleanup" {
  provisioner "local-exec" {
    when    = destroy
    command = "echo Cleaning up external registration"
  }
}

resource "null_resource" "build_assets" {
  triggers = {
    app_version = var.app_version
  }

  provisioner "local-exec" {
    command = "echo Building assets for ${var.app_version}"
  }
}

resource "aws_eip" "web" {
  domain = "vpc"

  provisioner "local-exec" {
    command = "echo ${self.public_ip}"
  }
}

resource "aws_instance" "app" {
  ami           = data.aws_ami.ubuntu.id
  instance_type = "t3.micro"

  provisioner "file" {
    source      = "./entire-app-directory"
    destination = "/tmp/app"
  }

  provisioner "remote-exec" {
    inline = [
      "sudo apt-get update -y",
      "sudo apt-get install -y docker.io",
      "sudo mv /tmp/app /opt/app",
      "sudo docker compose up -d"
    ]
  }
}

terraform {
  backend "http" {}
}

resource "aws_s3_bucket_policy" "assets" {
  #checkov:skip=CKV_AWS_70:Intentional public-read bucket for tutorial static website example
  bucket = aws_s3_bucket.assets.id
  policy = data.aws_iam_policy_document.assets_public_read.json
}

resource "aws_s3_bucket_policy" "bad" {
  bucket = aws_s3_bucket.data.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = "*"
      Action = "s3:GetObject"
      Resource = "${aws_s3_bucket.data.arn}/*"
    }]
  })
}

resource "aws_ebs_volume" "data" {
